CREATE   VIEW [Subs].[vwSubsInvoices] AS

	SELECT 
		 [Account_Num] AS 'Account Num'
		,[SubsCampaign] AS 'Subs Campaign'
		,[Campaign_Year] AS 'Campaign Year'
		,[Full_Invoice_Amount_CUR] AS 'Full Invoice Amount CUR'
		,[Full_Invoice_Amount_GBP] AS 'Full Invoice Amount GBP'
		,[Invoice_Amount_CUR] AS 'Invoice Amount CUR'
		,[Invoice_Amount_GBP] AS 'Invoice Amount GBP'
		,[Settle_Amount_CUR] AS 'Settle Amount CUR'
		,[Settle_Amount_GBP] AS 'Settle Amount GBP'
		,[Order_Num.] AS 'Order No.'
		,[Invoice] AS 'Invoice'
		,[Voucher] AS 'Voucher'
		,[Trans_Date] AS 'Trans Date'
		,Inv_Currency AS 'Currency'
		,[Exchange_Rate] AS 'Exchange Rate'
		,[Exchange_Adjustment] AS 'Exchange Adjustment'
		,Inv_Payment_Method AS 'Payment Method'
		,[Last_Settle_Voucher] AS 'Last Settle Voucher'
		,[Last_Settle_Date] AS 'Last Settle Date'
		,[Trans_Type_Code] AS 'Trans Type Code'
		,[Trans_Type] AS 'Trans Type'
		,[Country_Code] AS 'Country Code'
		,[Rec_ID] AS 'Rec ID'
		,[Discount_(Max)] AS 'Discount (Max)'
		,Has_Concession AS 'Has Concession'
		,Retired_Concession AS 'Retired Concession'
		,[100%_Concession] AS '100% Concession'
		,[Non_Subs_Amount_CUR] AS 'Non-Subs Amount CUR'
		,[Non_Subs_Amount_GBP] AS 'Non-Subs Amount GBP'
		,[Inv_Credit_Amount_CUR] AS 'Inv Credit Amount CUR'
		,[Inv_Credit_Amount_GBP] AS 'Inv Credit Amount GBP'
		,[Fully_Credited] AS 'Fully Credited'
		,[Credit_Diff] AS 'Credit Diff'
		,[Paid_Amount_CUR] AS 'Paid Amount CUR'
		,[Paid_Amount_GBP] AS 'Paid Amount GBP'
		,[Balance_CUR] AS 'Balance CUR'
		,[Balance_GBP] AS 'Balance GBP'
		,[APP_Invoice_Flag] AS 'App Invoice Flag'
		,[Payment_Status] AS 'Payment Status'
	FROM [Subs].[tblSubsInvoices]
